L000481	\sectionprl{Appendix A: Explicit expressions for the symmetry-based NFH equations}
L000482	We present explicit expressions for the parameters in the symmetry-based NFH equations. See the SM for the details~\cite{SM1}. From the time-reversal symmetry, the inverse of the covariance matrix can be written in general as
L000483	\begin{align}
L000484	\Co^{-1} &= \begin{pmatrix}
L000485	a_1 & 0 & a_0 \\
L000486	0 & 1 & 0 \\
L000487	a_0 & 0 & a_3
L000488	\end{pmatrix}.
L000489	\end{align}
L000490	We set $[\Co^{-1}]_{2,2}:=1$ without loss of generality.
L000491	By requiring a Gaussian steady state of the Fokker–Planck equation, the following relations are obtained:
L000492	\begin{align}
L000493	D \Co =& B , \label{eq:FDT1 main}\\
L000494	A \Co  =& \Co A^T, \label{eq:FDT2}\\
L000495	\iCH^a_{bc} =&\iCH^b_{ca}=\iCH^c_{ab}, \label{potential condition main}
L000496	\end{align}
L000497	where $\iCH^a_{bc}:=\sum_d [\Co^{-1}]_{ad}H^d_{bc}$.
L000498	Combined with Eqs.~(\ref{eq:FDT1 main})–(\ref{potential condition main}),
L000499	the conservation law $\partial_t u_1 - \partial_x u_2 = 0$ and
L000500	time-reversal symmetry of the equations of motion
L000501	yield the general expressions for the coefficients in Eq.~(\ref{EOM original main}):
L000502	\begin{align}
L000503	A &= \begin{pmatrix}
L000504	0 & -1 & 0 \\
L000505	a_0 P - a_1 & 0 & a_3 P - a_0 \\
L000506	0 & P & 0
L000507	\end{pmatrix}, \label{A matrix} \\
L000508	D
L000509	&= \begin{pmatrix}
L000510	0 & 0 & 0 \\
L000511	0 & D_{22} & 0 \\
L000512	(a_0 / a_3) D_{33} & 0 & D_{33}
L000513	\end{pmatrix}, \\
L000514	B
L000515	&= \begin{pmatrix}
L000516	0 & 0 & 0 \\
L000517	0 & D_{22} & 0 \\
L000518	0 & 0 & D_{33} / a_3
L000519	\end{pmatrix},\label{B matrix}\\
L000520	H^1 &= {\bm 0}, \\
L000521	H^2 &= \begin{pmatrix}
L000522	\Hgll& 0 & (a_3/a_0) \Hgll\\
L000523	0 & \Hggg & 0 \\
L000524	(a_3/a_0) \Hgll& 0 & (a_3^2 / a_0^2) \Hgll
L000525	\end{pmatrix},\\
L000526	H^3 &= \begin{pmatrix}
L000527	0 & (1/a_0) \Hgll & 0 \\
L000528	(1/a_0) \Hgll & 0 & (a_3/a_0^2) \Hgll \\
L000529	0 & (a_3/a_0^2) \Hgll & 0
L000530	\end{pmatrix}, \label{H3 matrix main}
L000531	\end{align}
L000532	where we have introduced the parameters $P=A_{32}$
L000533	
L000534	
L000535	By transforming the variables from $u$ to $\phi$, the equivalent general expressions for parameters automatically emerge as follows
L000536	\begin{align}
L000537	 \cs&=\sqrt{a_3 P^2-2 a_0 P+a_1}, \label{cs, D_0, D_s} \\
L000538	    D_0&=\frac{a_1 a_3-a_0^2 }{a_3 (a_3 P^2-2 a_0P+a_1)}D_{33}, \\
L000539	    D_s&=\frac{a_3^2 P^2-2 a_3 a_0 P+a_0^2 }{2 a_3 (a_3P^2-2 a_0 P+a_1)}D_{33}+\frac{1}{2}D_{22},
L000540	\end{align}
L000541	\begin{align}
L000542	    G^+&=\begin{pmatrix}
L000543	        -\lambda_3 & \lambda_2 & -\lambda_4\\
L000544	        \lambda_2 & \lambda_1 & 0 \\
L000545	        -\lambda_4 & 0 &\lambda_4
L000546	    \end{pmatrix}, \,
L000547	       G^-=\begin{pmatrix}
L000548	        -\lambda_4 & 0 & \lambda_4\\
L000549	        0 & -\lambda_1 & -\lambda_2 \\
L000550	        \lambda_4 &-\lambda_2& \lambda_3
L000551	    \end{pmatrix},\\
L000552	        G^0&=\begin{pmatrix}
L000553	        \lambda_2 & \lambda_1 & 0\\
L000554	         \lambda_1 & 0 & -\lambda_1 \\
L000555	        0 &-\lambda_1& -\lambda_2
L000556	    \end{pmatrix}. \label{parametrized Gmatrix}
L000557	\end{align}
L000558	Here, we parameterize the matrix $G$ with the parameters $\lambda_i~(i=1,2,3, 4)$.
L000559	
