L000561	\sectionprl{Appendix B: Renormalization group analysis}
L000562	Self energies by the one loop diagrams in Fig.~\ref{fig:self-energy} is explicitly written as
L000563	\begin{align}
L000564	\Xi^{\alpha}(k_1,\omega_1)=k_1^2&\sum_{\mu,\nu}G^\alpha_{\mu\nu}G^\alpha_{\mu\nu}\int^>_{k_2} \bSf^\mu_{k_+}\bSf^\nu_{k_-},\label{Xi main}\\
L000565	\Sigma^{\alpha}(k_1,\omega_1)=4k_1&\sum_{\mu,\nu} G^\alpha_{\mu\nu}G^\mu_{\alpha \nu}\int^>_{k_2} k_+ \Gf^\mu_{k_+}\bSf^\nu_{k_-},\label{Sigma main}\\
L000566	    \Gamma^\alpha_{\beta \gamma}(k_1,k_2, \omega_1,\omega_2)&= -4k_1 \sum_{\mu,\nu,\rho} G^\alpha_{\mu \rho}G^\beta_{\mu \nu}G^\gamma_{\nu\rho} {V}^\mu_{\nu\rho},\label{Gamma}
L000567	\end{align}
L000568	where $\Gf_k^{\alpha}:=1/(\omega -\alpha\cs k+i D_\alpha k^2)$ and $\bSf^\alpha_k:=2D_\alpha k^2/[(\omega-\alpha\cs k)^2+D_\alpha^2k^4]$.
L000569	Similarly, vertex corrections given by the one loop diagram in Fig.~\ref{fig:vertex-corrections} yield the following expression
L000570	\begin{align}
L000571	V^{\mu}_{\nu\rho}&(k_1,k_2, \omega_1,\omega_2) =\int_q^> \bigl[
L000572	    q(k_++q) \Gf^\mu_{k_++q}\Gf^\nu_q\bSf^\rho_{k_--q}\nonumber \\
L000573	    &+q(k_-+q) \Gf^\rho_{k_-+q}\Gf^\nu_q\bSf^\mu_{k_+-q}
L000574	   \nonumber \\
L000575	   &+(k_++q)(k_--q)\Gf^\mu_{k_++q}\bSf^\nu_q\Gf^\rho_{k_--q}
L000576	    \bigr].
L000577	\end{align}
L000578	These self energies and vertex corrections result in the RG equations~(\ref{RG eq Ds})--(\ref{RG eq c lambda}).
