L001062	\section{fluctuating hydrodynamics in normal modes  for the general case and path integral representation}
L001063	\subsection{Fluctuating hydrodynamics in normal modes  for the general case }
L001064	\label{sec:action1}
L001065	We derive the fluctuating hydrodynamics for the normal modes for the general case satisfying the parameters in the section \ref{sec:generalcase}.
L001066	The inverse Green function corresponding to Eq.~(\ref{EOM original}) in Fourier space is
L001067	\begin{align}
L001068	    \tilde{\Gf}^{-1}(k,\omega) =\omega\mathcal{I} -kA+ik^2D.
L001069	\end{align}
L001070	where $\mathcal{I}$ is the $3 \times 3$ identity matrix. We diagonalize $\tilde{\Gf}^{-1}$ by the $k$-dependent matrix $R(k)$:
L001071	\begin{align}
L001072	    \Gf^{-1}(k, \omega)&:=R(k) \tilde{\Gf}^{-1}( k, \omega )R^{-1}(k),\\
L001073	    &=\begin{pmatrix}
L001074	     \omega-\cs k+iD_sk^2 &0 &0 \\
L001075	        0& \omega+iD_0k^2 &0\\
L001076	        0 & 0 & \omega+\cs k+iD_sk^2
L001077	    \end{pmatrix}
L001078	    +O(k^3),
L001079	\end{align}
L001080	where $c_s$ is the sound velocity, and $D_0$ and $D_s$ are the diffusion constants for the heat and sound modes, respectively.
L001081	These coefficients are obtained as
L001082	\begin{align}
L001083	 \cs&=\sqrt{a_3 P^2-2 a_0 P+a_1},\\
L001084	    D_0&=\frac{a_1 a_3-a_0^2 }{a_3 (a_3 P^2-2 a_0P+a_1)}D_{33},\\
L001085	    D_s&=\frac{a_3^2 P^2-2 a_3 a_0 P+a_0^2 }{2 a_3 (a_3P^2-2 a_0 P+a_1)}D_{33}+\frac{1}{2}D_{22}.
L001086	\end{align}
L001087	
L001088	The normal modes are defined by
L001089	\begin{align}
L001090	    \phi_\alpha(k)=\sum_a R_{\alpha a}(k)u_a(k),
L001091	\end{align}
L001092	with $\alpha = +, 0, -$ corresponding to the right-moving sound, heat, and left-moving sound modes, respectively.
L001093	The equilibrium correlation matrix in the normal-mode basis is given by
L001094	\begin{align}
L001095	\Cn(k) := R(k) \Co R^T(-k),
L001096	\end{align}
L001097	and has diagonal components of order $O(k^0)$ and off-diagonal components of order $O(k^1)$.
L001098	We neglect the off-diagonal components and use the arbitrariness of $R$
L001099	to normalize the diagonal components, so that $\Cn = I$.
L001100	
L001101	
L001102	The nonlinear couplings in the normal-mode basis are given by
L001103	\begin{align}
L001104	    G^\alpha_{\beta\gamma}:=\sum_{a,b,c}R_{\alpha a}(0)H^a_{bc}R^{-1}_{b\beta}(0)R^{-1}_{c\gamma}(0),
L001105	\end{align}
L001106	where we have retained only the lowest-order term in $k$ since higher-order terms are irrelevant. These couplings satisfy
L001107	\begin{align}
L001108	    G^\alpha_{\beta \gamma}&=G^\alpha_{\gamma \beta},\\
L001109	    G^\alpha_{\beta \gamma}&=-G^{-\alpha}_{-\beta -\gamma},\label{G symmetry1}\\
L001110	    G^\alpha_{\beta \gamma}&=G^\beta_{\gamma \alpha}.\label{G symmetry2}
L001111	\end{align}
L001112	Here, the symmetries in Eqs.~(\ref{G symmetry1}) and (\ref{G symmetry2}) correspond to the time-reversal symmetry and the equilibrium condition (\ref{potential condition}), respectively.
L001113	Since the detailed expressions of the parameters introduced earlier is not required for the RG calculation, we reparametrize the $G$ matrix as
L001114	\begin{align}
L001115	    G^+&=\begin{pmatrix}
L001116	        -\lambda_3 & \lambda_2 & -\lambda_4\\
L001117	        \lambda_2 & \lambda_1 & 0 \\
L001118	        -\lambda_4 & 0 &\lambda_4
L001119	    \end{pmatrix},\label{parametrized_Gmatrix1}\\
L001120	    G^0&=\begin{pmatrix}
L001121	        \lambda_2 & \lambda_1 & 0\\
L001122	         \lambda_1 & 0 & -\lambda_1 \\
L001123	        0 &-\lambda_1& -\lambda_2
L001124	    \end{pmatrix},\\
L001125	       G^-&=\begin{pmatrix}
L001126	        -\lambda_4 & 0 & \lambda_4\\
L001127	        0 & -\lambda_1 & -\lambda_2 \\
L001128	        \lambda_4 &-\lambda_2& \lambda_3
L001129	    \end{pmatrix}. \label{parametrized_Gmatrix3}
L001130	\end{align}
L001131	Note that the expressions (\ref{parametrized_Gmatrix1})-(\ref{parametrized_Gmatrix3}) are equivalent to (\ref{supple_h1}), (\ref{H2 matrix}) and (\ref{H3 matrix}).
L001132	With these couplings, the fluctuating hydrodynamic equations in the normal modes read
L001133	\begin{align}
L001134	    \biggl(\partial_t  +\alpha \cs \partial_x -D_\alpha \partial_x^2 \biggr)\phi^\alpha +\sum_{\beta, \gamma}G^\alpha_{\beta\gamma}\partial_x(\phi^\beta\phi^\gamma)&=\zeta^\alpha,\label{EOM normal}\\
L001135	    \langle \zeta^\alpha(x,t)\zeta^\beta(x',t')\rangle&=-2D_\alpha \delta_{\alpha\beta}\partial_x^2\delta(t-t')\delta(x-x'),
L001136	\end{align}
L001137	where $D_+ = D_- = D_s$ and we have imposed the fluctuation-dissipation relation to determine the noise intensity.
