L001139	\subsection{Path integral representation}
L001140	\label{sec:action2}
L001141	We represent the stochastic dynamics using the Martin–Siggia–Rose–Janssen–de~Dominicis (MSRJD) path-integral formalism. The partition functional $Z$ is written as
L001142	\begin{align}
L001143	    Z&= \int \mathcal{D} \phi^\alpha\mathcal{D}\pi^\alpha e^{-I_0[\phi,\pi]+I_{int}[\phi,\pi]},\\
L001144	    I_0[\phi,\pi]&=\sum_\alpha\int_k \frac{1}{2}
L001145	    \begin{pmatrix}
L001146	        \phi^\alpha_{-k} &\pi^\alpha_{-k}
L001147	    \end{pmatrix}
L001148	    \begin{pmatrix}
L001149	        0 &  1/g^\alpha_{-k}
L001150	 \\
L001151	  1/g^\alpha_{k}
L001152	& 2D_\alpha k^2
L001153	    \end{pmatrix}
L001154	    \begin{pmatrix}
L001155	        \phi^\alpha_{k} \\
L001156	        \pi^\alpha_{k}
L001157	    \end{pmatrix},\label{eq:I0}\\
L001158	I_{\mathrm{int}}[\phi,\pi]&=-\sum_{\alpha,\beta,\gamma}\int_{k_1}\int_{k_2}k_1 G^\alpha_{\beta\gamma}
L001159	 \pi^\alpha_{-k_1} \phi^{\beta}_{k_+}\phi^{\gamma}_{k_-}.  \label{eq:Iint}
L001160	\end{align}
L001161	Here, $\omega$ denotes the frequency, $k$ the wavenumber, and $\pi_k^\alpha$ the auxiliary field.
L001162	We have introduced the following abbreviated notations:
L001163	\begin{align}
L001164	    \phi^\alpha_k &= \phi^\alpha(k,\omega), \\
L001165	    \int_k &= \int_{-\Lambda}^{\Lambda} \frac{dk}{2\pi}
L001166	              \int_{-\infty}^{\infty} \frac{d\omega}{2\pi}, \\
L001167	    k_\pm &= \frac{1}{2}k_1 \pm k_2, \\
L001168	    \omega_\pm &= \frac{1}{2}\omega_1 \pm \omega_2,
L001169	\end{align}
L001170	where $\Lambda$ is the wavenumber cutoff.
L001171	
L001172	
L001173	The zeroth-order correlation functions are calculated as
L001174	\begin{align}
L001175	\langle \phi^\alpha_{k_1}\pi_{k_2}^\beta  \rangle_0
L001176	 &=\frac{1}{Z_0}\int \mathcal{D}\phi^\alpha\mathcal{D}\pi^\alpha \phi^\alpha_{k_1}  \pi_{k_2}^\beta  e^{-I_0},\\
L001177	    &= g^\alpha_{k_1}
L001178	\delta_{\alpha\beta}\delta_{k_1,-k_2},\\
L001179	\langle \phi_{k_1}^\alpha \phi^\beta_{k_2} \rangle_0
L001180	    &= \bSf^\alpha_{k_1}\delta_{\alpha\beta}\delta_{k_1,-k_2},\\
L001181	    \langle \pi_{k_1}^\alpha \pi^\beta_{k_2} \rangle_0&=0,
L001182	\end{align}
L001183	where we have introduced
L001184	\begin{align}
L001185	    Z_0&= \int \mathcal{D}\phi^\alpha\mathcal{D}\pi^\alpha   e^{-I_0},\\
L001186	     g_k^\alpha
L001187	&=\frac{1}{\omega -\alpha\cs k+iD_\alpha k^2},\\
L001188	    \bSf^\alpha_{k} &= \frac{2D_\alpha k^2}{(\omega-\alpha \cs k)^2+D_\alpha^2k^4},\\
L001189	    \delta_{k_1,-k_2}&=(2\pi)^2\delta(k_1+k_2)\delta(\omega_1+\omega_2).
L001190	\end{align}
