L001193	\section{Relevance and irrelevance of terms from scaling analysis}
L001194	\label{scaling analysis}
L001195	We estimate the relevance or irrelevance of each term at long distances by performing a scaling analysis.
L001196	For simplicity, we consider the following fluctuating hydrodynamic equation for a single-component field $\phi(x,t)$:
L001197	\begin{align}
L001198	    (\partial_t - D \partial_x^2)\phi
L001199	    + \sum_{n=1}^\infty \sum_{m=2}^\infty
L001200	      \lambda_{n,m} \, \partial_x^n \phi^m
L001201	    &= \zeta , \\
L001202	    \langle \zeta(x,t) \zeta(x',t') \rangle
L001203	    &= -2 D \partial_x^2
L001204	       \delta(x - x') \delta(t - t') ,
L001205	\end{align}
L001206	where this expression represents the most general nonlinear contribution consistent with a derivative expansion in $\partial_x$ and $\phi$, and $\lambda_{n,m}$ denotes the corresponding expansion coefficients.
L001207	
L001208	We assume that the noise $\zeta$ satisfies the fluctuation–dissipation relation and that $\phi$ is a conserved field, implying $n \geq 1$.
L001209	This form corresponds to the expansion of ${\cal J}$ discussed in Sec.~\ref{FHD from derivative expansion}.
L001210	Note that the number of components of $\phi$ does not affect the following argument.
L001211	The corresponding MSRJD action is given by
L001212	\begin{align}
L001213	 I_0 &= \int dt\, dx \, \bigl[i\pi(\partial_t - D\partial_x^2)\phi - \pi D\partial_x^2\pi\bigr],\\
L001214	    I_{\mathrm{int}} &= \int dt\, dx \sum_{n=1}^\infty \sum_{m=2}^\infty \lambda_{n,m}\,i\pi\,\partial_x^n\phi^m.
L001215	\end{align}
L001216	
L001217	We next perform the scaling transformation
L001218	\begin{align}
L001219	    x \to bx, \quad
L001220	    t \to b^z t, \quad
L001221	    \phi \to b^{\alpha_{\phi}}\phi, \quad
L001222	    \pi \to b^{\alpha_{\pi}}\pi,
L001223	    \label{scaling transformation}
L001224	\end{align}
L001225	where $z$, $\alpha_\phi$, and $\alpha_\pi$ are scaling exponents determined from scale invariance.
L001226	Under this transformation, the Gaussian part of the action, $I_0$, becomes
L001227	\begin{align}
L001228	    I_0 = \int dt\, dx \, \biggl[
L001229	        b^{\alpha_\phi+\alpha_\pi+1}i\pi\bigl(\partial_t - b^{z-2}D\partial_x^2\bigr)\phi
L001230	        - b^{z+2\alpha_\pi-1}D\pi \partial_x^2\pi
L001231	    \biggr].
L001232	\end{align}
L001233	The action $I_0$ remains invariant under the choice
L001234	\begin{align}
L001235	    z = 2, \quad \alpha_\phi = \alpha_\pi = -\tfrac{1}{2}, \label{EW exponent}
L001236	\end{align}
L001237	which corresponds to the Edwards–Wilkinson (EW) fixed point.
L001238	For the EW exponents, the interaction term becomes
L001239	\begin{align}
L001240	    I_{\mathrm{int}}=\int dt\, dx \sum_{n,m} b^{5/2-m/2-n}\,\lambda_{n,m}\,i\pi\,\partial_x^n \phi^m.
L001241	\end{align}
L001242	Terms with  positive (negative) scaling exponents are relevant (irrelevant), while the choice $b>1$ corresponds to probing the long-distance behavior.
L001243	For $n \ge 1$ and $m \ge 2$, the only relevant combination is
L001244	\begin{align}
L001245	    n = 1, \quad m = 2. \label{sup:relevant}
L001246	\end{align}
L001247	The term with $n = 1$ and $m = 3$ is marginal, having zero scaling exponent,
L001248	and may contribute to anomalous scaling in the RG analysis.
L001249	However, we can neglect it, since the relevant term~(\ref{sup:relevant})
L001250	dominates the scaling behavior.
L001251	We also remark that the derivation of the model in Sec.~\ref{FHD from derivative expansion}
L001252	can be made more systematic within the MSRJD path-integral formalism,
L001253	which provides a natural framework for constructing an effective field theory.
L001254	
L001255	
L001256	We also consider the Gaussian action with a finite sound velocity,
L001257	\begin{align}
L001258	    I_0&=\int dt\, dx \biggl[i\pi\bigl(\partial_t+\cs\partial_x-D\partial_x^2\bigr)\phi-D\pi \partial_x^2\pi\biggr].
L001259	\end{align}
L001260	Under the scaling transformation (\ref{scaling transformation}), $I_0$ transforms as
L001261	\begin{align}
L001262	    I_0=\int dt\, dx \biggl[b^{\alpha_\phi+\alpha_\pi+1}i\pi\bigl(\partial_t+b^{z-1}\cs\partial_x-b^{z-2}D\partial_x^2\bigr)\phi
L001263	    -b^{z+2\alpha_\pi-1}D\pi \partial_x^2\pi\biggr].
L001264	\end{align}
L001265	Choosing $z=1$ renders the diffusion constant irrelevant,
L001266	\begin{align}
L001267	    D \to b^{-1}D,
L001268	\end{align}
L001269	which indicates that the theory becomes nondissipative at large scales and is therefore unphysical.
L001270	For the EW exponents (\ref{EW exponent}), we find
L001271	\begin{align}
L001272	    I_0=\int dt\, dx \biggl[i\pi\bigl(\partial_t+b \cs\partial_x-D\partial_x^2\bigr)\phi-D\pi \partial_x^2\pi\biggr],
L001273	\end{align}
L001274	where $\cs$ appears to increase with $b$, thereby breaking scale invariance.
L001275	We argue, however, that this apparent scaling of $\cs$ is superficial rather than physical.
L001276	A more detailed discussion of this issue will be given in the main text and in Sec.~\ref{about sound speed}.
L001277	
L001278	
L001279	
L001280	\section{Renormalization group analysis}
L001281	In Wilson’s renormalization group, we integrate out modes in the wavenumber shell $\Lambda - \delta \Lambda \leq |k| \leq \Lambda$.
L001282	We decompose the fields into short- and long-wavelength components:
L001283	\begin{align}
L001284	    \phi^\alpha_k &=\phi^{\alpha,>}_k+\phi^{\alpha,<}_k,\\
L001285	    \phi^{\alpha,>}_k &=\theta(\Lambda-\delta\Lambda-|k|)\phi^\alpha_k,\\
L001286	    \phi^{\alpha,<}_k &=\theta(|k|-\Lambda+\delta\Lambda)\phi^\alpha_k,
L001287	\end{align}
L001288	where  $\theta(k)$ is the Heaviside step function.
L001289	$\pi^\alpha$ is also decomposed in the same way.
L001290	Integrating over the short-wavelength components, we obtain a coarse-grained effective action $I_R$:
L001291	\begin{align}
L001292	    Z&=\int\mathcal{D}\phi^{\alpha,<} \mathcal{D}\pi^{\alpha,<} \mathcal{D}\phi^{\alpha,>} \mathcal{D}\pi^{\alpha,>} e^{-I_0+I_{\rm int}},\\
L001293	    &=\int\mathcal{D}\phi^{\alpha,<} \mathcal{D}\pi^{\alpha,<} e^{-I_R}.
L001294	\end{align}
L001295	which is formally expressed in terms of the self-energies $\Sigma^\alpha(k,\omega)$ and $\Xi^\alpha(k,\omega)$, and vertex corrections $\Gamma^\alpha_{\beta\gamma}(k_1,k_2,\omega_1,\omega_2)$:
L001296	\begin{align}
L001297	    I_R
L001298	    =&\int_k \frac{1}{2}
L001299	    \begin{pmatrix}
L001300	        \phi^{\alpha,<}_{-k} &\pi^{\alpha,<}_{-k}
L001301	    \end{pmatrix}
L001302	    \begin{pmatrix}
L001303	        0 & 1/g^\alpha_{-k}
L001304	+\Sigma_{-k}^\alpha \\
L001305	    1/g^\alpha_{k}
L001306	+\Sigma_{k}^\alpha  & 2D_\alpha k^2+2\Xi^\alpha_k
L001307	    \end{pmatrix}
L001308	    \begin{pmatrix}
L001309	        \phi^{\alpha,<}_{k} \\
L001310	        \pi^{\alpha,<}_{k}
L001311	    \end{pmatrix}\nonumber \\
L001312	    &-\int_{k_1}\int_{k_2}\biggl[\biggl(k_1 G^\alpha_{\beta\gamma}+\Gamma^\alpha_{\beta\gamma}\biggr)\pi^{\alpha,<}_{-k_1}\phi^{\beta,<}_{k_+}\phi^{\gamma,<}_{k_-} \biggr],
L001313	\end{align}
L001314	
L001315	In the Wilson RG,  the self-energies and vertex corrections are computed perturbatively in $G^\alpha_{\beta\gamma}$.
L001316	From the one-loop calculation, we obtain the following self energies (See the diagrams shown in Figs.2 and 3 of the End matter in the main text.)
L001317	\begin{align}
L001318	\Xi^{\alpha}(k,\omega)=k^2\sum_{\mu,\nu}G^\alpha_{\mu\nu}G^\alpha_{\mu\nu}\int^>_{k_2} \bSf^\mu_{k_+}\bSf^\nu_{k_-},\label{Xi}\\
L001319	\Sigma^{\alpha}(k,\omega)=4k\sum_{\mu,\nu} G^\alpha_{\mu\nu}G^\mu_{\alpha \nu}\int^>_{k_2} k_+ g^\mu_{k_+}
L001320	\bSf^\nu_{k_-},\label{Sigma}
L001321	\end{align}
L001322	where we have introduced the notations
L001323	\begin{align}
L001324	    \int_{k}^>&=\int_{\Lambda-\delta\Lambda \leq |k|\leq \Lambda}\frac{dk}{2\pi}\int^{\infty}_{-\infty}\frac{d\omega}{2\pi},
L001325	\end{align}
L001326	They satisfy the relation $\operatorname{Im} \Sigma^\alpha_k = \Xi^\alpha_k$ which corresponds to the fluctuation–dissipation theorem.
L001327	The vertex correction at one-loop order is calculated as
L001328	\begin{align}
L001329	    \Gamma^\alpha_{\beta \gamma}(k_1,k_2,\omega_1,\omega_2)=& -4k_1 \sum_{\mu,\nu,\rho} G^\alpha_{\mu \rho}G^\beta_{\mu \nu}G^\gamma_{\nu\rho} {V}^\mu_{\nu\rho}(k_1,k_2,\omega_1,\omega_2),\label{Gamma}\\
L001330	    V^{\mu}_{\nu\rho}(k_1,k_2,\omega_1,\omega_2):=&\int_q^> \biggl[
L001331	    q(k_++q)  g^\mu_{k_++q} g^\nu_q
L001332	\bSf^\rho_{k_--q} +q(k_-+q) g^\rho_{k_-+q} g^\nu_q
L001333	\bSf^\mu_{k_+-q} +(k_++q)(k_--q)g^\mu_{k_++q}\bSf^\nu_q g^\rho_{k_--q}
L001334	    \biggr].\label{eq:def of V}
L001335	\end{align}
L001336	
L001337	We define the renormalization corrections to the parameters as the expansion coefficients of the self energies and vertex correction in $k$ and $\omega$
L001338	\begin{align}
L001339	    \delta D_0 &=\frac{1}{2i}\lim_{\omega, k \to 0}\partial_k^2\Sigma^0_k, \\
L001340	    \delta D_s &=\frac{1}{2i}\lim_{\omega, k \to 0}\partial_k^2\Sigma^\sigma_k, \\
L001341	    \delta \cs   &=-\frac{1}{\sigma}\lim_{\omega, k \to 0}\partial_k\Sigma^\sigma_k,\\
L001342	    \delta G^\alpha_{\beta\gamma} &=\lim_{\omega_1,\omega_2, k_1,k_2 \to 0}\partial_{k_1}\Gamma^\alpha_{\beta\gamma},
L001343	\end{align}
L001344	where $\sigma=\pm$.
L001345	The renormalization corrections to $\delta \lambda_i$ are given by $\delta G^\alpha_{\beta\gamma}$, with the indices corresponding to those in Eqs.~(\ref{parametrized_Gmatrix1})-(\ref{parametrized_Gmatrix3}):
L001346	\begin{align}
L001347	    \delta \lambda_1=\delta G^+_{00},\\
L001348	    \delta \lambda_2=\delta G^+_{+0},\\
L001349	    \delta \lambda_3=\delta G^-_{--},\\
L001350	    \delta \lambda_4=\delta G^+_{--}.
L001351	\end{align}
L001352	
L001353	From Eqs.~(\ref{Xi})-(\ref{Gamma}), we obtain
L001354	\begin{align}
L001355	\delta D_s=&\delta\Lambda\biggl[\frac{\lambda _1^2}{  \pi \Lambda^2   D_0}+\frac{4 \lambda_2^2(D_0+D_s)}{\pi (c_s^2+\Lambda (D_0+D_s))^2}+\frac{\lambda _3^2}{  \pi \Lambda^2  D_s}+\frac{\lambda_4^2(\cs^2+3 \Lambda^2  D_s^2)}{    \pi \Lambda^2  D_s(   c_s^2+ \Lambda ^2 D_s^2)}\biggr],\\
L001356	\delta D_0 =& \delta \Lambda\biggl[\frac{8\lambda_1^2 (D_0+D_s)}{\pi  (c_s^2+\Lambda^2(D_0+D_s)^2)}+\frac{2\lambda_2^2}{\pi  \Lambda^2 D_s}\biggr], \\
L001357	\delta \cs =& \delta \lambda_i = 0.
L001358	\end{align}
L001359	where the subscripts $i=1,2,3$ and $4$. Note that the parameters $\lambda_i$ are defined in (\ref{parametrized_Gmatrix1})-(\ref{parametrized_Gmatrix3}).
L001360	Here, we note that the sound velocity and all the nonlinear couplings $\lambda_i$ do not have the RG corrections.
L001361	In the one component noisy Burgers equation, a nonlinear coupling $\lambda$ is not renormalized due to the pseudo-Galilean symmetry.
L001362	Our multi-component model does not have  such simple Galilean invariance. Thus, the RG correction is written as
L001363	\begin{align}
L001364	    \delta G^\alpha_{\beta\gamma}=-4 \sum_{\mu,\nu,\rho} G^\alpha_{\mu \rho}G^\beta_{\mu \nu}G^\gamma_{\nu\rho} {V}^\mu_{\nu\rho}(0,0),
L001365	\end{align}
L001366	 where ${V}^\mu_{\nu\rho}(0,0)$ vanishes for all components $\mu$, $\nu$ and $\rho$.
L001367	This might indicate the existence of some extended pseudo-Galilean symmetry.
L001368	
L001369	Dividing the RG corrections by $\delta \Lambda$, we obtain the RG equation
L001370	\begin{align}
L001371	            -\Lambda\frac{d D_s}{d \Lambda} =&D_s \biggl[\frac{\lambda _1^2}{  \pi \Lambda   D_sD_0}+\frac{4 \lambda_2^2\Lambda(D_0+D_s)}{\pi D_s(c_s^2+\Lambda (D_0+D_s))^2}+\frac{\lambda _3^2}{  \pi \Lambda  D_s^2}+\frac{\lambda_4^2(\cs^2+3 \Lambda^2  D_s^2)}{    \pi \Lambda  D_s^2(   c_s^2+  \Lambda ^2 D_s^2)}\biggr],\\
L001372	    -\Lambda\frac{d D_0}{d \Lambda} =&D_0 \biggl[\frac{8\lambda_1^2 \Lambda(D_0+D_s)}{\pi D_0 (c_s^2+\Lambda^2(D_0+D_s)^2)}+\frac{2\lambda_2^2}{\pi  \Lambda D_0D_s}\biggr],\\
L001373	              -\Lambda\frac{d \cs}{d \Lambda} =&0,\label{eq:RG_c}\\
L001374	           -\Lambda\frac{d \lambda_i}{d \Lambda} =&0.\label{eq:RG_lambda}
L001375	\end{align}
L001376	For later convenience, we collectively denote the parameters $D_0, D_s, \cs$ and $\lambda_i$ by $X$, and introduce the corresponding function $\eta_X$ as in the following equation
L001377	\begin{align}
L001378	    -\Lambda \frac{d X}{d\Lambda}=X \cdot \eta_{X}.
L001379	\end{align}
L001380	We note that $\eta_X$ gives the anomalous exponent
L001381	\begin{align}
L001382	    X \sim \Lambda^{-\eta_X}.
L001383	\end{align}
