L001385	\subsection{Fixed points and scaling exponents}
L001386	Fixed points of RG flow are defined in dimensionless parameter space.
L001387	To define dimensionless parameters, we perform the dimensional analysis.
L001388	From the fact that the dimension of the action $[I]$ is $1$, we obtain
L001389	\begin{align}
L001390	    [\omega]&=[D_\alpha\Lambda^2],\\
L001391	    [\pi^\alpha_k]&=[D_\alpha^{-1}\Lambda^{-5/2}],\\
L001392	    [\phi^\alpha_k]&=[D_\alpha^{-1}\Lambda^{-5/2}],\\
L001393	    [\cs]&=[D_\alpha \Lambda],\\
L001394	    [\lambda_i]&=[\Lambda^{1/2}D_\alpha].
L001395	\end{align}
L001396	 We make the parameters dimensionless on the basis of $D_s$ and $\Lambda$ as
L001397	\begin{align}
L001398	    \tcs &= \frac{\cs}{D_s\Lambda},\label{eq:Def of tilde c}\\
L001399	    \tD &= \frac{D_0}{D_s}, \label{eq:Def of tilde D}\\
L001400	    \tl_i &= \frac{\lambda_i}{\pi^{1/2}D_s\Lambda^{1/2}}, \label{eq:Def of tilde lambda}
L001401	\end{align}
L001402	In terms of the dimensionless parameters, the anomalous exponents are expressed as
L001403	\begin{align}
L001404	    \eta_{D_s}&=\frac{\tl_1^2}{\tD}+\frac{4 \tl_2^2(\tD+1) }{\tcs^2+(\tD+1)^2}+\tl_3^2+\frac{\tl_4^2(\tcs^2+3)}{\tcs^2+1}, \label{fdslambda}\\
L001405	    \eta_{D_0}&=\frac{2}{\tD}\biggl(\frac{4 (\tD+1) \tl_1^2}{\tcs^2+(\tD+1)^2}+\tl_2^2\biggr), \label{fd0lambda}\\
L001406	    \eta_{\cs}&=\eta_{\lambda_i}=0. \label{f c lambda}
L001407	\end{align}
L001408	Differentiating Eqs.~(\ref{eq:Def of tilde c})-(\ref{eq:Def of tilde lambda}) with respect to $\Lambda$ and using Eq. (\ref{f c lambda}),
L001409	 we arrive at the RG equations for the dimensionless parameters
L001410	\begin{align}
L001411	  -\Lambda\frac{d \tcs}{d \Lambda}
L001412	
L001413	          &=\tcs\biggl(1-\eta_{D_s}\biggr), \label{eq:eq:RG_tilde c}\\
L001414	     -\Lambda\frac{d  \tilde{D}}{d \Lambda}
L001415	     &= \tilde{D}\biggl(\eta_{D_0}-\eta_{D_s}\biggr),\label{eq:RG_tildeddd}\\
L001416	          -\Lambda\frac{d \tl_i}{d \Lambda}
L001417	
L001418	          &=\tl_i\biggl(\frac{1}{2}-\eta_{D_s}\biggl),\label{eq:RG_tilde lambda}
L001419	\end{align}
L001420	The fixed points are given by zeros of the r.h.s of these equations. We have the two solutions
L001421	\begin{align}
L001422	    \tcs^*=\tl_i^*=0,\label{eq:FP2}
L001423	\end{align}
L001424	and
L001425	\begin{align}
L001426	    \tcs^*=0, \quad \eta_{D_0}^*=\eta_{D_s}^*=\frac{1}{2}.\label{eq:FP1}
L001427	\end{align}
L001428	The first solution (\ref{eq:FP2}) is the EW fixed point and trivial.
L001429	In contrast, the anomalous exponents (\ref{eq:FP1}) provide the non-trivial scalings of the parameters
L001430	\begin{align}
L001431	 D_0 \sim \Lambda^{-1/2},\; D_s \sim \Lambda^{-1/2},  \;
L001432	&\cs \sim \Lambda^{0}, \; \lambda_i \sim \Lambda^0.
L001433	\end{align}
L001434	By using Eqs.~(\ref{fdslambda}) and (\ref{fd0lambda}) with $\tilde{c}_s=0$, we find that the anomalous exponents $\eta_{D_0}=1/2$ and $\eta_{D_s}=1/2$ are realized with real parameters $\tilde{\lambda}_{i}~ (i=1,\cdots ,4)$ for the following two cases
L001435	\begin{align}
L001436	({\rm A}): 1 \le \tilde{D} \le 7 \, ,~~~~~~~~~~~~~({\rm B}): 0 < \tilde{D} \le 7 - 4 \sqrt{3} \, .
L001437	\end{align}
L001438	
L001439	For case (A), the parameters can be chosen as
L001440	\begin{align}
L001441	\tilde{\lambda}_2^2 &\le \frac{1}{4}\,
L001442	\frac{\tilde{D}(7-\tilde{D})(\tilde{D}+1)}{16 \tilde{D} - (\tilde{D}+1)^2},\\
L001443	\tilde{\lambda}_1^2 &= \frac{\tilde{D}(\tilde{D}+1)}{16}
L001444	 - \frac{(\tilde{D}+1)\tilde{\lambda}_2^2}{4},\\
L001445	\tilde{\lambda}_3^2 + 3 \tilde{\lambda}_4^2
L001446	 &= \frac{1}{2} - \frac{\tilde{\lambda}_1^2}{\tilde{D}}
L001447	 - \frac{4 \tilde{\lambda}_2^2}{\tilde{D}+1} \ (\ge 0).
L001448	\end{align}
L001449	Similarly, for case (B), the parameters are chosen as
L001450	\begin{align}
L001451	\frac{\tilde{D}}{4} &\ge \tilde{\lambda}_2^2 \ge
L001452	\frac{1}{4}\,\frac{\tilde{D}(7-\tilde{D})(\tilde{D}+1)}{16 \tilde{D} - (\tilde{D}+1)^2},\\
L001453	\tilde{\lambda}_1^2 &= \frac{\tilde{D}(\tilde{D}+1)}{16}
L001454	 - \frac{(\tilde{D}+1)\tilde{\lambda}_2^2}{4},\\
L001455	\tilde{\lambda}_3^2 + 3 \tilde{\lambda}_4^2
L001456	 &= \frac{1}{2} - \frac{\tilde{\lambda}_1^2}{\tilde{D}}
L001457	 - \frac{4 \tilde{\lambda}_2^2}{\tilde{D}+1} \ (\ge 0).
L001458	\end{align}
L001459	For both cases, we have numerically investigated the RG flow of Eqs.~(\ref{eq:RG_tildeddd}) and (\ref{eq:RG_tilde lambda}) with $\tilde{c}_s = 0$.
L001460	We have confirmed that an attractive parameter regime exists.
L001461	For the flow of the sound velocity, see the main text (Section~``Remarks on the sound velocities in the RG'').
L001462	
L001463	
L001464	To obtain the dynamic scaling exponent $z$, we consider the inverse of the Green function near the fixed point (\ref{eq:FP1})
L001465	\begin{align}
L001466	    (\Gf^{-1})^\alpha(\omega, k)&\sim \omega+i\bar{D}_\alpha  \Lambda^{-1/2}k^2,
L001467	\end{align}
L001468	where $\bar{D}_\alpha$ is the constant being independent of $\Lambda$. We note that the sound velocity vanishes at the fixed point, $\tcs^*=0$.
L001469	We perform the rescaling $k \to b^{-1}k$, $\Lambda \to b^{-1}\Lambda$ and $\omega \to b^{-z}\omega$ and have
L001470	\begin{align}
L001471	       (\Gf^{-1})^\alpha(b^{-z}\omega, b^{-1}k)&=b^{-z}\biggl( \omega+ib^{z-3/2}\bar{D}_\alpha  \Lambda^{-1/2}k^2\biggr).
L001472	\end{align}
L001473	Therefore, $\Gf^{-1}$ scales with $z=3/2$, which is the same value of the KPZ exponent.
L001474	We note that both of the heat and sound modes has the exponents $z=3/2$.
L001475	
L001476	
L001477	\subsection{  sound velocity and scaling relations}
L001478	\label{about sound speed}
L001479	We consider the one-component Burgers equation with a sound velocity
L001480	\begin{align}
L001481	\partial_t \phi+\partial_x\biggl(\cs \phi-\partial_x D \phi+ \lambda \phi^2
L001482	\biggr)&=\eta,\\
L001483	\langle\eta(x,t)\eta(x',t')\rangle &= -2D \partial_x^2\delta(x-x')\delta(t-t'),
L001484	\end{align}
L001485	which is derived from the usual Burgers equation by the transformation $x \to x+\cs t$.
L001486	Then, the space-time correlation function exactly obeys Prah\"{o}fer–Spohn scaling function with the argument
L001487	\begin{align}
L001488	\Sf(x,t)= t^{-{2/3}}f \biggl(\frac{x-\cs t}{t^{2/3}}\biggr).
L001489	\end{align}
L001490	On the one hand, the one-loop calculation gives the following RG equations
L001491	\begin{align}
L001492	    -\Lambda\frac{\partial \cs}{\partial \Lambda}&=0,\\
L001493	        -\Lambda\frac{\partial \lambda}{\partial \Lambda}&=0,\\
L001494	    -\Lambda\frac{\partial D}{\partial \Lambda}&=D\tl^2,\label{eq:dD}\\
L001495	     -\Lambda\frac{\partial \tilde{c}_s}{\partial \Lambda}&=\tilde{c}_s\biggl(1-\tl^2\biggr),\\
L001496	      -\Lambda\frac{\partial \tl}{\partial \Lambda}&=\tl\biggl(\frac{1}{2}-\tl^2\biggr).
L001497	\end{align}
L001498	The KPZ fixed point reads
L001499	\begin{align}
L001500	    \tilde{c}_s^*=0, \quad (\tl^*)^2=\frac{1}{2},
L001501	\end{align}
L001502	where we again find that the sound velocity vanishes at the KPZ fixed point.
L001503	Therefore, in the standard RG analysis, the dimensionless sound velocity apparently increases near the fixed point as
L001504	\begin{align}
L001505	    \tcs \sim \Lambda^{-1/2}.
L001506	\end{align}
L001507	This apparent increase is superficial, and the scaling exponent is independent of the sound velocity since it can be eliminated by the coordinate transformation.
L001508	The difficulty arises because the propagating mode obeys a scaling relation involving $x+\cs t$ and $t$, rather than $x$ and $t$.
L001509	Consequently, the conventional RG scheme cannot straightforwardly capture this behavior and effectively treats the system in the limit of vanishing sound velocity.
