L001540	\subsection{Numerical implementation}
L001541	To numerically solve our model, we use a scheme based on the method of Garcia, Bell, and others~\cite{Garcia2024-nq}, which combines a spatial discretization on a staggered grid~\cite{BalboaUsabiaga2012-sh, Srivastava2023-nx} with a third-order stochastic Runge-Kutta (RK3) method for time integration~\cite{Delong2013-fh, Srivastava2023-nx}.
L001542	
L001543	The core idea of the staggered grid is to define scalar quantities and their associated fluxes at different locations in the computational domain.
L001544	We first divide the one-dimensional space into a series of cells of width $a_{\rm uv}$.
L001545	As illustrated in Fig.~\ref{supfig0}, the scalar fields $\phi^{\alpha}_i$ are defined at the center of each cell (indexed by integers $i=1,2,\cdots,N$), while the fluxes $\mathcal{J}^{\alpha}_{i+1/2}$ are defined at the boundaries between cells (indexed by half-integers $i+1/2$).
L001546	
L001547	This staggered arrangement provides a natural and robust discretization of the conservation law:
L001548	\begin{align}
L001549	    \frac{d \phi^{\alpha}_{i}}{d t} = - \frac{\mathcal{J}^{\alpha}_{i+1/2} - \mathcal{J}^{\alpha}_{i-1/2}}{a_{\rm uv}}, \label{eq:appendix_discrete_continuity}
L001550	\end{align}
L001551	where
L001552	\begin{align}
L001553	    \mathcal{J}^{\alpha}_{i+1/2} = \alpha c_s \phi^{\alpha}_{i+1/2} - D_{\alpha} (\partial_x \phi^{\alpha})_{i+1/2} + \sum_{\beta,\gamma} G^{\alpha}_{\beta\gamma} (\phi^{\beta}\phi^{\gamma})_{i+1/2} + \theta^{\alpha}_{i+1/2}. \label{eq:appendix_discrete_flux}
L001554	\end{align}
L001555	To complete the spatial discretization, the flux $\mathcal{J}^{\alpha}_{i+1/2}$ at the cell boundary must be expressed in terms of the scalar variables $\phi^{\alpha}_{i}$ at the cell centers.
L001556	We approximate the individual terms in Eq.~(\ref{eq:appendix_discrete_flux}) as follows:
L001557	\begin{enumerate}
L001558	    \item Advection term [$\alpha c_s \phi^{\alpha}_{i+1/2}$]: This term is approximated by
L001559	    \begin{align}
L001560	        \alpha c_s \phi^{\alpha}_{i+1/2} = \alpha c_s \frac{\phi^{\alpha}_{i+1} + \phi^{\alpha}_{i}}{2}.
L001561	    \end{align}
L001562	    \item Diffusion term [$D_{\alpha} (\partial_x \phi^{\alpha})_{i+1/2}$]: This term is approximated by
L001563	    \begin{align}
L001564	        D_{\alpha} (\partial_x \phi^{\alpha})_{i+1/2} =D_{\alpha} \frac{\phi^{\alpha}_{i+1} - \phi^{\alpha}_{i}}{a_{\rm uv}}.
L001565	    \end{align}
L001566	    \item Nonlinear term [$G^{\alpha}_{\beta\gamma} (\phi^{\beta}\phi^{\gamma})_{i+1/2}$]: This term is approximated by
L001567	    \begin{align}
L001568	        G^{\alpha}_{\beta\gamma} (\phi^{\beta}\phi^{\gamma})_{i+1/2} = G^{\alpha}_{\beta\gamma} \left(\frac{\phi^{\beta}_{i} \phi^{\gamma}_{i+1} + \phi^{\beta}_{i+1} \phi^{\gamma}_{i}}{12} + \frac{\phi^{\beta}_{i} \phi^{\gamma}_{i} + \phi^{\beta}_{i+1} \phi^{\gamma}_{i+1}}{6}\right).
L001569	    \end{align}
L001570	    Importantly, in the absence of noise, this formulation strictly conserves the quantity
L001571	    $\sum_{\alpha=+,-,0} (\phi^{\alpha})^2$~\cite{Delong2013-fh}.
L001572	\end{enumerate}
L001573	
L001574	
L001575	The semi-discrete equations Eq.~(\ref{eq:appendix_discrete_continuity}) form a system of stochastic ordinary differential equations.
L001576	We can write this system compactly as:
L001577	\begin{align}
L001578	\frac{d \phi^{\alpha}_{i}}{d t} = F^{\alpha}_i(\bm{\phi}) + \eta^{\alpha}_i[\bm{\theta}],
L001579	\end{align}
L001580	where $F^{\alpha}_i(\bm{\phi})$ is related to the deterministic part of the flux, $\mathcal{J}^{\alpha}_{\text{det}, i+1/2}$, (including the advection, diffusion, and nonlinear terms), and $\eta^{\alpha}_i[\bm{\theta}]$ is the stochastic part:
L001581	\begin{align}
L001582	F^{\alpha}_i[\bm{\phi}] &= - \frac{\mathcal{J}^{\alpha}_{\text{det}, i+1/2} - \mathcal{J}^{\alpha}_{\text{det}, i-1/2}}{a_{\rm uv}}, \\
L001583	\eta^{\alpha}_i[\bm{\theta}] &= - \frac{\theta^{\alpha}_{i+1/2}(t) - \theta^{\alpha}_{i-1/2}(t)}{a_{\rm uv}}.
L001584	\end{align}
L001585	
L001586	We integrate this system using the RK3 scheme~\cite{Delong2013-fh, Srivastava2023-nx}.
L001587	The update from time $t_n$ to $t_{n+1}$ proceeds via two intermediate fields, $\phi_{i}^{\alpha}(t_{n+1/3})$ and $\phi_{i}^{\alpha}(t_{n+2/3})$:
L001588	\begin{align}
L001589	\phi_{i}^{\alpha}(t_{n+1/3}) &= \phi_{i}^{\alpha}(t_n) + \Delta t F^{\alpha}_i[\bm{\phi}(t_n)] + \Delta t \eta^{\alpha}_i[\bm{\theta}(t_n)], \\
L001590	\phi_{i}^{\alpha}(t_{n+2/3}) &= \frac{3}{4} \phi_{i}^{\alpha}(t_n) + \frac{1}{4} \left(\phi_{i}^{\alpha}(t_{n+1/3}) + \Delta t F^{\alpha}_i[\bm{\phi}(t_{n+1/3})] + \Delta t \eta^{\alpha}_i[\bm{\theta}(t_{n+1/3})] \right), \\
L001591	\phi_{i}^{\alpha}(t_{n+1}) &= \frac{1}{3} \phi_{i}^{\alpha}(t_n) + \frac{2}{3} \left(\phi_{i}^{\alpha}(t_{n+2/3}) + \Delta t F^{\alpha}_i[\bm{\phi}(t_{n+2/3})] + \Delta t \eta^{\alpha}_i[\bm{\theta}(t_{n+2/3})] \right).
L001592	\end{align}
L001593	
L001594	The stochastic terms $\eta^{\alpha}_i[\bm{\theta}(t_n)]$, $\eta^{\alpha}_i[\bm{\theta}(t_{n+1/3})]$, and $\eta^{\alpha}_i[\bm{\theta}(t_{n+2/3})]$ are constructed as follows.
L001595	First, at the beginning of each time step, two independent arrays of Gaussian random numbers $\xi^{\alpha}_{A, i+1/2}$ and $\xi^{\alpha}_{B, i+1/2}$ are generated at each cell boundary from a standard normal distribution (mean $0$, variance $1$).
L001596	The stochastic term $\theta_{i+1/2}^{\alpha}(t_{n+k/3})$ for each stage is then constructed as
L001597	\begin{align}
L001598	\theta_{i+1/2}^{\alpha}(t_{n+k/3}) = \sqrt{\frac{2 D_{\alpha}}{a_{\rm uv} \Delta t}} \left( \xi^{\alpha}_{A, i+1/2} + \beta_k \xi^{\alpha}_{B, i+1/2} \right),
L001599	\end{align}
L001600	where the coefficients $\beta_{k}$ for the three stages are given by
L001601	\begin{align*}
L001602	  \beta_0 &= \frac{2\sqrt{2} + \sqrt{3}}{5}, \\
L001603	  \beta_1 &= \frac{-4\sqrt{2} + 3\sqrt{3}}{5}, \\
L001604	  \beta_2 &= \frac{\sqrt{2} - 2\sqrt{3}}{10}.
L001605	\end{align*}
L001606	Finally, $\eta^{\alpha}_i[\bm{\theta}(t_{n+k/3})]$ is simply the discrete divergence of the stochastic flux:
L001607	\begin{align}
L001608	    \eta^{\alpha}_i[\bm{\theta}(t_{n+k/3})] &= - \frac{\theta^{\alpha}_{i+1/2}(t_{n+k/3}) - \theta^{\alpha}_{i-1/2}(t_{n+k/3})}{a_{\rm uv}}.
L001609	\end{align}
L001610	
